function reconcile(desired, currentPods) {
  const actions = [];
  if (currentPods.length < desired) {
    for (let i = currentPods.length; i < desired; i++) {
      actions.push({ action: "create", pod: "pod-" + (i + 1) });
    }
  } else if (currentPods.length > desired) {
    for (let i = currentPods.length; i > desired; i--) {
      actions.push({ action: "delete", pod: currentPods[i - 1] });
    }
  }
  return actions;
}
